BEGIN TRANSACTION;
CREATE TABLE activity_claim_cursors (
                        guild_id INTEGER NOT NULL,
                        user_id INTEGER NOT NULL,
                        claimed_voice_seconds INTEGER NOT NULL DEFAULT 0,
                        claimed_messages INTEGER NOT NULL DEFAULT 0,
                        last_claimed_at TEXT,
                        last_source TEXT,
                        PRIMARY KEY (guild_id, user_id)
                    );
CREATE TABLE admin_audit_logs (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        guild_id INTEGER NOT NULL,
                        actor_id INTEGER NOT NULL,
                        action TEXT NOT NULL,
                        target_user_id INTEGER,
                        target_resource_id TEXT,
                        before_data_json TEXT NOT NULL DEFAULT '{}',
                        after_data_json TEXT NOT NULL DEFAULT '{}',
                        reason TEXT,
                        created_at TEXT NOT NULL
                    );
CREATE TABLE economy_reward_claims (
                        guild_id INTEGER NOT NULL,
                        user_id INTEGER NOT NULL,
                        reward_key TEXT NOT NULL,
                        last_claimed_at TEXT NOT NULL,
                        last_claim_date TEXT,
                        claim_count INTEGER NOT NULL DEFAULT 0,
                        PRIMARY KEY (guild_id, user_id, reward_key)
                    );
CREATE TABLE economy_transactions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        guild_id INTEGER NOT NULL,
                        user_id INTEGER NOT NULL,
                        actor_id INTEGER,
                        type TEXT NOT NULL,
                        amount INTEGER NOT NULL,
                        balance_before INTEGER NOT NULL,
                        balance_after INTEGER NOT NULL,
                        reason TEXT,
                        metadata_json TEXT NOT NULL DEFAULT '{}',
                        created_at TEXT NOT NULL
                    );
CREATE TABLE guild_settings (
                        guild_id INTEGER PRIMARY KEY,
                        currency_name TEXT NOT NULL DEFAULT 'pontos',
                        voice_points_per_minute INTEGER NOT NULL DEFAULT 2,
                        message_points INTEGER NOT NULL DEFAULT 1,
                        activity_provider TEXT NOT NULL DEFAULT 'native',
                        economy_channel_id INTEGER,
                        shop_channel_id INTEGER,
                        staff_log_channel_id INTEGER,
                        min_voice_seconds_to_claim INTEGER NOT NULL DEFAULT 60,
                        min_messages_to_claim INTEGER NOT NULL DEFAULT 1,
                        ignore_afk_channel INTEGER NOT NULL DEFAULT 1,
                        ignore_bots INTEGER NOT NULL DEFAULT 1,
                        count_voice_when_alone INTEGER NOT NULL DEFAULT 0,
                        max_admin_grant_per_use INTEGER NOT NULL DEFAULT 100000,
                        economy_manager_role_id INTEGER,
                        created_at TEXT NOT NULL,
                        updated_at TEXT NOT NULL
                    , casino_max_bet INTEGER NOT NULL DEFAULT 1000, casino_daily_profit_limit INTEGER NOT NULL DEFAULT 5000, casino_min_bet_coin_flip INTEGER NOT NULL DEFAULT 1, casino_min_bet_dice INTEGER NOT NULL DEFAULT 1, casino_min_bet_slot INTEGER NOT NULL DEFAULT 1, casino_min_bet_roulette INTEGER NOT NULL DEFAULT 1, casino_min_bet_mascot_race INTEGER NOT NULL DEFAULT 1, casino_min_bet_duel INTEGER NOT NULL DEFAULT 1, casino_min_bet_blackjack INTEGER NOT NULL DEFAULT 1, casino_min_bet_scratch_card INTEGER NOT NULL DEFAULT 1, casino_min_bet_collective_race INTEGER NOT NULL DEFAULT 1, casino_min_bet_match_bet INTEGER NOT NULL DEFAULT 1, casino_limiters_enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE native_message_stats (
                        guild_id INTEGER NOT NULL,
                        channel_id INTEGER NOT NULL,
                        user_id INTEGER NOT NULL,
                        message_count INTEGER NOT NULL DEFAULT 0,
                        last_message_at TEXT,
                        PRIMARY KEY (guild_id, channel_id, user_id)
                    );
CREATE TABLE native_voice_sessions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        guild_id INTEGER NOT NULL,
                        user_id INTEGER NOT NULL,
                        channel_id INTEGER NOT NULL,
                        started_at TEXT NOT NULL,
                        ended_at TEXT,
                        duration_seconds INTEGER,
                        is_valid INTEGER NOT NULL DEFAULT 1,
                        invalid_reason TEXT
                    );
CREATE TABLE reward_codes (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        guild_id INTEGER NOT NULL,
                        reward_id INTEGER NOT NULL,
                        code_encrypted TEXT NOT NULL,
                        is_claimed INTEGER NOT NULL DEFAULT 0,
                        claimed_by INTEGER,
                        claimed_at TEXT,
                        created_at TEXT NOT NULL,
                        FOREIGN KEY(reward_id) REFERENCES reward_items(id)
                    );
CREATE TABLE reward_items (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        guild_id INTEGER NOT NULL,
                        name TEXT NOT NULL,
                        description TEXT NOT NULL,
                        type TEXT NOT NULL,
                        price INTEGER NOT NULL,
                        stock_quantity INTEGER,
                        stock_mode TEXT NOT NULL DEFAULT 'LIMITED',
                        max_per_user INTEGER,
                        role_id INTEGER,
                        delivery_message TEXT,
                        is_active INTEGER NOT NULL DEFAULT 1,
                        created_by INTEGER NOT NULL,
                        created_at TEXT NOT NULL,
                        updated_at TEXT NOT NULL,
                        deleted_at TEXT
                    );
CREATE TABLE reward_purchases (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        guild_id INTEGER NOT NULL,
                        user_id INTEGER NOT NULL,
                        reward_id INTEGER NOT NULL,
                        transaction_id INTEGER,
                        price_paid INTEGER NOT NULL,
                        status TEXT NOT NULL DEFAULT 'COMPLETED',
                        delivery_status TEXT NOT NULL DEFAULT 'PENDING',
                        metadata_json TEXT NOT NULL DEFAULT '{}',
                        created_at TEXT NOT NULL,
                        delivered_at TEXT,
                        FOREIGN KEY(reward_id) REFERENCES reward_items(id),
                        FOREIGN KEY(transaction_id) REFERENCES economy_transactions(id)
                    );
CREATE TABLE user_wallets (
                        guild_id INTEGER NOT NULL,
                        user_id INTEGER NOT NULL,
                        balance INTEGER NOT NULL DEFAULT 0,
                        total_earned INTEGER NOT NULL DEFAULT 0,
                        total_spent INTEGER NOT NULL DEFAULT 0,
                        created_at TEXT NOT NULL,
                        updated_at TEXT NOT NULL,
                        PRIMARY KEY (guild_id, user_id)
                    );
CREATE INDEX idx_economy_transactions_guild_user_created
                    ON economy_transactions(guild_id, user_id, created_at DESC)
                    ;
CREATE INDEX idx_native_voice_sessions_guild_user
                    ON native_voice_sessions(guild_id, user_id, started_at DESC)
                    ;
CREATE INDEX idx_native_voice_sessions_open
                    ON native_voice_sessions(guild_id, user_id, ended_at)
                    ;
CREATE INDEX idx_native_message_stats_guild_user
                    ON native_message_stats(guild_id, user_id)
                    ;
CREATE INDEX idx_reward_items_guild_active
                    ON reward_items(guild_id, is_active, price)
                    ;
CREATE INDEX idx_reward_purchases_guild_user_created
                    ON reward_purchases(guild_id, user_id, created_at DESC)
                    ;
CREATE INDEX idx_reward_purchases_reward_user
                    ON reward_purchases(guild_id, reward_id, user_id)
                    ;
CREATE INDEX idx_economy_reward_claims_user
                    ON economy_reward_claims(guild_id, user_id, reward_key)
                    ;
DELETE FROM "sqlite_sequence";
COMMIT;
